+                      "    pm.expect(policy.payments).to.have.lengthOf(1);",
+                      "    pm.expect(policy.payments[0]).to.include({ type: sold.paymentMethod, amount: sold.amount });",
+                      "    pm.expect(policy.payments[0].reference).to.be.a(\"string\").and.not.empty;",
+                      "    pm.expect(policy.terms[0].paymentReference).to.eql(policy.payments[0].reference);",
