+using System.Net;
+using Uinsure.Policies.Api.Tests.Builders;
+using Uinsure.Policies.Api.Tests.Support;
+using Xunit;
+
+namespace Uinsure.Policies.Api.Tests;
+
+// The concurrency row of the contract, through the records: a sold policy (POST → GET) saved from a stale copy
+// answers 409 /problems/concurrency with no ruleId and a detail that asks for a retry, the stored policy reads
+// back as sold, and the concurrency token is PolicyRecord.Version, never a Domain type's. The stale save is the
+// factory's test path (F1 has no write endpoint that changes a stored policy).
+// No Rule trait: concurrency is not a numbered rule.
+public sealed class ConcurrencyConflictTests : IClassFixture<StaleSaveApiFactory>
+{
+    private const string ConcurrencyType = "/problems/concurrency";
+
+    private readonly StaleSaveApiFactory _factory;
+
+    public ConcurrencyConflictTests(StaleSaveApiFactory factory)
+    {
+        _factory = factory;
+        _factory.ResetClock();
+    }
+
+    [Fact]
+    public async Task Stale_save_of_a_sold_policy_answers_409_concurrency_with_no_ruleId()
+    {
+        using var client = _factory.CreateClient();
+        await client.SellAndReadBack(SellPolicyRequestBuilder.Distinctive("STALE-409").Build(), "STALE-409");
+
+        using var response = await client.PostAsync(StaleSaveApiFactory.PathFor("STALE-409"), content: null, TestContext.Current.CancellationToken);
+
+        var problem = await ProblemAssert.TransportProblem(response, HttpStatusCode.Conflict, StaleSaveApiFactory.Path, ConcurrencyType);
+        Assert.Equal("The policy was changed by another request", problem.Member("title").GetString());
+        Assert.Equal("Retry the request.", problem.Member("detail").GetString());
+    }
+
+    [Fact]
+    public async Task Stale_save_of_a_sold_policy_leaves_it_reading_back_as_sold()
+    {
+        using var client = _factory.CreateClient();
+        var sold = SellPolicyRequestBuilder.Distinctive("STALE-READ-BACK").Build();
+        await client.SellAndReadBack(sold, "STALE-READ-BACK");
+
+        using var response = await client.PostAsync(StaleSaveApiFactory.PathFor("STALE-READ-BACK"), content: null, TestContext.Current.CancellationToken);
+        Assert.Equal(HttpStatusCode.Conflict, response.StatusCode);
+
+        using var read = await client.GetPolicy("STALE-READ-BACK");
+        Assert.Equal(HttpStatusCode.OK, read.StatusCode);
+        SoldPolicyAssert.ReadsBackAsSold(await read.ReadJson(), sold, "STALE-READ-BACK", new DateOnly(2027, 11, 15));
+    }
+
+    [Fact]
+    public async Task Stale_save_conflicts_on_the_Version_of_the_PolicyRecord()
+    {
+        using var client = _factory.CreateClient();
+        await client.SellAndReadBack(SellPolicyRequestBuilder.Distinctive("STALE-RECORD").Build(), "STALE-RECORD");
+
+        using var response = await client.PostAsync(StaleSaveApiFactory.PathFor("STALE-RECORD"), content: null, TestContext.Current.CancellationToken);
+
+        Assert.Equal(HttpStatusCode.Conflict, response.StatusCode);
+        Assert.Equal("Uinsure.Policies.Persistence.Records.PolicyRecord", _factory.ConcurrencyTokenOwner);
+    }
+}
diff --git a/tests/Uinsure.Policies.Api.Tests/Support/StaleSaveApiFactory.cs b/tests/Uinsure.Policies.Api.Tests/Support/StaleSaveApiFactory.cs
new file mode 100644
index 00000000..4f6ecb9f
--- /dev/null
+++ b/tests/Uinsure.Policies.Api.Tests/Support/StaleSaveApiFactory.cs
@@ -0,0 +1,94 @@
+using Microsoft.AspNetCore.Builder;
+using Microsoft.AspNetCore.Hosting;
+using Microsoft.AspNetCore.Http;
+using Microsoft.AspNetCore.TestHost;
+using Microsoft.EntityFrameworkCore;
+using Microsoft.EntityFrameworkCore.ChangeTracking;
+using Microsoft.Extensions.DependencyInjection;
+using Uinsure.Policies.Domain.Policies;
+using Uinsure.Policies.Persistence;
+using Uinsure.Policies.Services;
+
+namespace Uinsure.Policies.Api.Tests.Support;
+
+// The API plus a test-only path that makes a stale save of a sold policy, inside the app's own exception
+// handling exactly as a write endpoint would. F1 has no endpoint that changes a stored policy, so the path does
+// what a lost race does: it loads the policy through the app's IPolicyRepository, another request then loads
+// and saves the same policy with a new Version, and this request saves the copy it loaded. The repository's
+// PersistenceConflictException(Concurrency) is then answered by the app. The entry found is the tracked one
+// whose Version is EF's concurrency token, whatever its type; the factory records that type's name.
+public sealed class StaleSaveApiFactory : PoliciesApiFactory
+{
+    public const string Path = "/test/stale-save";
+
+    // The Version the other request saves: a literal, never Guid.NewGuid().
+    private static readonly Guid OtherRequestVersion = new("0f1b0000-0000-4000-8000-000000000001");
+
+    private readonly Lock _gate = new();
+    private string? _concurrencyTokenOwner;
+
+    // The full name of the tracked type whose Version is the concurrency token, seen on the last stale save.
+    public string? ConcurrencyTokenOwner
+    {
+        get
+        {
+            lock (_gate)
+            {
+                return _concurrencyTokenOwner;
+            }
+        }
+    }
+
+    public static string PathFor(string reference) => $"{Path}?reference={Uri.EscapeDataString(reference)}";
+
+    protected override void ConfigureWebHost(IWebHostBuilder builder)
+    {
+        base.ConfigureWebHost(builder);
+
+        builder.ConfigureTestServices(services =>
+            services.AddTransient<IStartupFilter>(_ => new StaleSaveEndpointStartupFilter(this)));
+    }
+
+    private static EntityEntry VersionedEntry(PoliciesDbContext context) =>
+        context.ChangeTracker.Entries().Single(entry => entry.Metadata.FindProperty("Version")?.IsConcurrencyToken == true);
+
+    private async Task StaleSave(HttpContext context)
+    {
+        var ct = context.RequestAborted;
+        var reference = new PolicyReference(context.Request.Query["reference"].ToString());
+        var repository = context.RequestServices.GetRequiredService<IPolicyRepository>();
+        if (await repository.GetByReference(reference, ct) is null)
+        {
+            throw new InvalidOperationException($"'{reference.Value}' was expected to be sold before the stale save.");
+        }
+
+        var mine = VersionedEntry(context.RequestServices.GetRequiredService<PoliciesDbContext>());
+        lock (_gate)
+        {
+            _concurrencyTokenOwner = mine.Metadata.ClrType.FullName;
+        }
+
+        // Another request loads the same policy and saves it first, with a new Version.
+        using (var other = context.RequestServices.GetRequiredService<IServiceScopeFactory>().CreateScope())
+        {
+            var otherContext = other.ServiceProvider.GetRequiredService<PoliciesDbContext>();
+            _ = await other.ServiceProvider.GetRequiredService<IPolicyRepository>().GetByReference(reference, ct);
+            VersionedEntry(otherContext).Property("Version").CurrentValue = OtherRequestVersion;
+            await otherContext.SaveChangesAsync(ct);
+        }
+
+        // This request saves the copy it loaded, which still carries the Version it was loaded with.
+        mine.State = EntityState.Modified;
+        await repository.SaveChanges(ct);
+        context.Response.StatusCode = StatusCodes.Status204NoContent;
+    }
+
+    private sealed class StaleSaveEndpointStartupFilter(StaleSaveApiFactory factory) : IStartupFilter
+    {
+        public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next) => app =>
+        {
+            next(app);
+            app.Map(Path, branch => branch.Run(factory.StaleSave));
+        };
+    }
+}

diff --git a/tests/Uinsure.Policies.Api.Tests/ClientAbortedRequestTests.cs b/tests/Uinsure.Policies.Api.Tests/ClientAbortedRequestTests.cs
new file mode 100644
index 00000000..41d04447
--- /dev/null
+++ b/tests/Uinsure.Policies.Api.Tests/ClientAbortedRequestTests.cs
@@ -0,0 +1,93 @@
+using System.Text;
+using Microsoft.Extensions.Logging;
+using Uinsure.Policies.Api.Tests.Builders;
+using Uinsure.Policies.Api.Tests.Support;
+using Xunit;
+
+namespace Uinsure.Policies.Api.Tests;
+
+// Transport row of the contract: a request the client aborts (an OperationCanceledException while
+// RequestAborted is cancelled) is not a server fault. Nobody is there to read a body, so no 500 problem body
+// is written, and it is logged at Information, never at Error. The sale goes through the real controller,
+// service and repository; only the repository's lookup is made to wait for the abort.
+// On the F1 code ASP.NET Core's ExceptionHandlerMiddleware already ends an aborted request with 499 and logs it
+// at Debug, before any IExceptionHandler runs: the no-500 and never-Error tests guard that, and the app's own
+// Information entry is the missing behaviour.
+// No Rule trait: transport hardening is not a numbered rule.
+public sealed class ClientAbortedRequestTests : IClassFixture<ClientAbortedApiFactory>
+{
+    private static readonly TimeSpan Patience = TimeSpan.FromSeconds(10);
+
+    private readonly ClientAbortedApiFactory _factory;
+
+    public ClientAbortedRequestTests(ClientAbortedApiFactory factory)
+    {
+        _factory = factory;
+        _factory.ResetClock();
+    }
+
+    [Fact]
+    public async Task Sale_aborted_by_the_client_gets_no_500_problem_body()
+    {
+        var served = await SellAndAbort("ABORT-NO-500");
+
+        Assert.True(served.Aborted, "The request was expected to end aborted.");
+        Assert.NotEqual(500, served.Status);
+        Assert.False(
+            served.ContentType?.StartsWith("application/problem+json", StringComparison.Ordinal) == true,
+            $"A problem body was written for an aborted request: {served.Status} {served.ContentType}.");
+    }
+
+    [Fact]
+    public async Task Sale_aborted_by_the_client_is_never_logged_at_Error()
+    {
+        await SellAndAbort("ABORT-NOT-ERROR");
+
+        Assert.DoesNotContain(_factory.Logs.Entries, entry =>
+            entry.Level >= LogLevel.Error && (entry.Exception is OperationCanceledException || entry.Message.Contains("/policies", StringComparison.Ordinal)));
+    }
+
+    [Fact]
+    public async Task Sale_aborted_by_the_client_is_logged_at_Information_by_the_app()
+    {
+        await SellAndAbort("ABORT-INFORMATION");
+
+        Assert.Contains(_factory.Logs.Entries, entry =>
+            entry.Level == LogLevel.Information
+            && entry.Category.StartsWith("Uinsure.Policies", StringComparison.Ordinal)
+            && entry.Message.Contains("/policies", StringComparison.Ordinal));
+    }
+
+    [Fact]
+    public async Task Sale_aborted_by_the_client_is_not_stored()
+    {
+        await SellAndAbort("ABORT-NOT-STORED");
+
+        using var client = _factory.CreateClient();
+        await client.AssertNotStored("ABORT-NOT-STORED");
+    }
+
+    // POST a valid sale, wait until its lookup is in flight, then abort it as a client that goes away does.
+    // Returns what the server ended the request with.
+    private async Task<ServedRequest> SellAndAbort(string reference)
+    {
+        var ct = TestContext.Current.CancellationToken;
+        var lookupWaiting = _factory.ArmLookup(reference);
+        var served = _factory.Served(reference);
+
+        using var client = _factory.CreateClient();
+        using var abort = CancellationTokenSource.CreateLinkedTokenSource(ct);
+        using var request = new HttpRequestMessage(HttpMethod.Post, "/policies")
+        {
+            Content = new StringContent(new SellPolicyRequestBuilder(reference).Build().ToJsonString(), Encoding.UTF8, "application/json"),
+        };
+        request.Headers.Add(ClientAbortedApiFactory.ProbeHeader, reference);
+
+        var sending = client.SendAsync(request, abort.Token);
+        await lookupWaiting.WaitAsync(Patience, ct);
+        await abort.CancelAsync();
+
+        await Assert.ThrowsAnyAsync<OperationCanceledException>(() => sending);
+        return await served.WaitAsync(Patience, ct);
+    }
+}
diff --git a/tests/Uinsure.Policies.Api.Tests/Support/ClientAbortedApiFactory.cs b/tests/Uinsure.Policies.Api.Tests/Support/ClientAbortedApiFactory.cs
new file mode 100644
index 00000000..2e57530c
--- /dev/null
+++ b/tests/Uinsure.Policies.Api.Tests/Support/ClientAbortedApiFactory.cs
@@ -0,0 +1,109 @@
+using System.Collections.Concurrent;
+using Microsoft.AspNetCore.Builder;
+using Microsoft.AspNetCore.Hosting;
+using Microsoft.AspNetCore.Http;
+using Microsoft.AspNetCore.TestHost;
+using Microsoft.Extensions.DependencyInjection;
+using Microsoft.Extensions.Logging;
+using Uinsure.Policies.Domain.Policies;
+using Uinsure.Policies.Services;
+
+namespace Uinsure.Policies.Api.Tests.Support;
+
+// What the server did with one request, seen from outside the app's whole pipeline (after its exception handling).
+public sealed record ServedRequest(int Status, string? ContentType, bool Aborted);
+
+// Production over HTTPS, for a sale the client gives up on. The app's IPolicyRepository is wrapped so a lookup
+// of an armed reference waits on the request's own token until the client aborts, as a slow database call does
+// when the client goes away; the OperationCanceledException then comes from the real controller → service →
+// repository path. A middleware ahead of the app's pipeline records the status and content type the server
+// ended with for each request carrying the probe header, and a logger provider captures what is logged.
+public sealed class ClientAbortedApiFactory : ProductionApiFactory
+{
+    public const string ProbeHeader = "X-Test-Abort-Probe";
+
+    private readonly ConcurrentDictionary<string, TaskCompletionSource> _reached = new(StringComparer.Ordinal);
+    private readonly ConcurrentDictionary<string, TaskCompletionSource<ServedRequest>> _served = new(StringComparer.Ordinal);
+
+    public ClientAbortedApiFactory() => ClientOptions.BaseAddress = TransportClients.HttpsBaseAddress;
+
+    public CapturingLoggerProvider Logs { get; } = new();
+
+    // Arms the next lookup of the reference only. The task completes once that lookup is waiting, so the test
+    // aborts mid-request, never before the request reaches the repository.
+    public Task ArmLookup(string reference) =>
+        _reached.GetOrAdd(reference, _ => new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously)).Task;
+
+    // Completes when the request with this probe value has left the app's pipeline.
+    public Task<ServedRequest> Served(string probe) => ServedSignal(probe).Task;
+
+    protected override void ConfigureWebHost(IWebHostBuilder builder)
+    {
+        base.ConfigureWebHost(builder);
+
+        builder.ConfigureTestServices(services =>
+        {
+            services.AddSingleton<ILoggerProvider>(Logs);
+            services.AddTransient<IStartupFilter>(_ => new ServedRequestRecorder(this));
+
+            var app = services.Single(descriptor => descriptor.ServiceType == typeof(IPolicyRepository));
+            var implementation = app.ImplementationType
+                ?? throw new InvalidOperationException("The app's IPolicyRepository is expected to be registered by type.");
+            services.Remove(app);
+            services.Add(new ServiceDescriptor(
+                typeof(IPolicyRepository),
+                provider => new StallingPolicyRepository((IPolicyRepository)ActivatorUtilities.CreateInstance(provider, implementation), this),
+                app.Lifetime));
+        });
+    }
+
+    private TaskCompletionSource<ServedRequest> ServedSignal(string probe) =>
+        _served.GetOrAdd(probe, _ => new TaskCompletionSource<ServedRequest>(TaskCreationOptions.RunContinuationsAsynchronously));
+
+    private sealed class ServedRequestRecorder(ClientAbortedApiFactory factory) : IStartupFilter
+    {
+        public Action<IApplicationBuilder> Configure(Action<IApplicationBuilder> next) => app =>
+        {
+            app.Use(async (context, nextMiddleware) =>
+            {
+                var probe = context.Request.Headers[ProbeHeader].ToString();
+                if (probe.Length == 0)
+                {
+                    await nextMiddleware(context);
+                    return;
+                }
+
+                try
+                {
+                    await nextMiddleware(context);
+                }
+                finally
+                {
+                    factory.ServedSignal(probe).TrySetResult(new ServedRequest(
+                        context.Response.StatusCode,
+                        context.Response.ContentType,
+                        context.RequestAborted.IsCancellationRequested));
+                }
+            });
+            next(app);
+        };
+    }
+
+    private sealed class StallingPolicyRepository(IPolicyRepository real, ClientAbortedApiFactory factory) : IPolicyRepository
+    {
+        public async Task<Policy?> GetByReference(PolicyReference reference, CancellationToken ct)
+        {
+            if (factory._reached.TryRemove(reference.Value, out var reached))
+            {
+                reached.TrySetResult();
+                await Task.Delay(Timeout.Infinite, ct);
+            }
+
+            return await real.GetByReference(reference, ct);
+        }
+
+        public void Add(Policy policy) => real.Add(policy);
+
+        public Task SaveChanges(CancellationToken ct) => real.SaveChanges(ct);
+    }
+}

